const comingSoon = {uk:'Добірки з’являться тут.',ru:'Здесь появятся подборки.',en:'Collections will appear here.',de:'Hier erscheinen die Sammlungen.',pl:'Tutaj pojawią się kolekcje.'};

function collectionCard(c) {
  const button=document.createElement('button');button.type='button';button.className='collection-card';const image=document.createElement('img');image.src=asset({id:c.cover},720);image.alt='';image.loading='lazy';const text=document.createElement('span'),name=document.createElement('strong'),detail=document.createElement('span'),count=document.createElement('small');name.textContent=c.names[lang];detail.textContent=c.descriptions[lang]||'';count.textContent=String(c.photos.length).padStart(2,'0')+' / '+groupTitle(c.group);text.append(name);if(detail.textContent)text.append(detail);text.append(count);button.append(image,text);button.onclick=()=>selectCollection(c.id);
  return button;
}

function renderCollections() {
  const nav = $('#collection-nav');
  nav.replaceChildren();
  const choices = collections.filter(c => active === 'all' || c.group === active);
  nav.hidden = choices.length === 0;

  if (active === 'people') {
    if (activeCollection) {
      const section = peopleSections.findIndex(direction => direction.ids.includes(activeCollection));
      if (section !== -1) activePeopleSection = section;
    }
    const panel = document.createElement('div');
    panel.className = 'filters';
    panel.setAttribute('role', 'group');
    panel.setAttribute('aria-label', groupTitle('people'));
    peopleSections.forEach((direction, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = direction.names[lang];
      button.setAttribute('aria-pressed', String(index === activePeopleSection));
      button.onclick = () => {
        activePeopleSection = index;
        selectCollection(null);
      };
      panel.append(button);
    });
    nav.append(panel);
  }

  if (activeCollection) {
    const description = choices.find(c => c.id === activeCollection).descriptions[lang];
    nav.hidden = active !== 'people' && !description;
    if (description) {
      const paragraph = document.createElement('p');
      paragraph.textContent = description;
      nav.append(paragraph);
    }
    return;
  }

  if (active !== 'people') {
    nav.append(...choices.map(collectionCard));
    return;
  }

  const direction = peopleSections[activePeopleSection];
  const matching = direction.ids.map(id => choices.find(c => c.id === id)).filter(Boolean);
  if (matching.length) {
    const grid = document.createElement('div');
    grid.className = 'collection-nav';
    grid.append(...matching.map(collectionCard));
    nav.append(grid);
  } else {
    const empty = document.createElement('p');
    empty.textContent = comingSoon[lang];
    nav.append(empty);
  }
}

function renderGallery(){const c=COPY[lang];$('#gallery-title').textContent=activeCollection?collections.find(c=>c.id===activeCollection).names[lang]:(active==='all'?allCollections[lang]:groupTitle(active));renderCollections();$('#count').hidden=!activeCollection;$('#count').textContent=activeCollection?String(visible().length).padStart(2,'0')+' / PHOTOGRAPHY':'';$('#filters').replaceChildren();['all',...groups].forEach(g=>{const b=document.createElement('button');b.textContent=g==='all'?allCollections[lang]:groupTitle(g);b.setAttribute('aria-pressed',String(active===g));b.onclick=()=>filter(g);$('#filters').append(b)});$('#gallery').replaceChildren();visible().forEach((p,i)=>{const f=document.createElement('figure');f.className='photo-card';const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',title(p));const img=document.createElement('img');img.src=asset(p,720);img.width=p.width;img.height=p.height;img.alt=title(p);img.loading='lazy';img.decoding='async';b.append(img);b.insertAdjacentHTML('beforeend',expand);b.onclick=()=>openViewer(i,b);const cap=document.createElement('figcaption');const t=document.createElement('span');t.textContent=title(p);const s=document.createElement('small');s.textContent=groupTitle(p.group);cap.append(t,s);f.append(b,cap);$('#gallery').append(f)});}
function render(){const c=COPY[lang];document.documentElement.lang=lang;document.title=({uk:'Фотографія',ru:'Фотография',en:'Photography',de:'Fotografie',pl:'Fotografia'})[lang]+' — Krystyna Mishchenko';document.querySelectorAll('[data-t]').forEach(e=>{const v=c[e.dataset.t];if(['headline','contactTitle'].includes(e.dataset.t))e.innerHTML=v;else e.textContent=v});$('#language').value=lang;document.querySelectorAll('a[href="index.html"], #hub-return').forEach(a=>{a.href='concepts.html?lang='+lang});renderHero();$('#series-grid').replaceChildren();groups.forEach((g,i)=>{const p=photos.find(p=>p.id===covers[i]),b=document.createElement('button');b.className='series-card';const img=document.createElement('img');img.src=asset(p,720);img.alt=groupTitle(g);img.loading='lazy';img.width=p.width;img.height=p.height;const s=document.createElement('span');s.className='series-name';s.textContent=groupTitle(g);const count=document.createElement('small');count.textContent=String(photos.filter(p=>p.group===g).length).padStart(2,'0');s.append(count);b.append(img,s);b.onclick=()=>filter(g,true);$('#series-grid').append(b)});const selected=$('#shoot-type').selectedIndex;$('#shoot-type').replaceChildren(...c.types.map(t=>new Option(t,t)));$('#shoot-type').selectedIndex=Math.max(0,selected);['close','prev','next'].forEach(id=>$('#'+id).setAttribute('aria-label',c[id]));$('#filters').setAttribute('aria-label',c.series);$('#viewer').setAttribute('aria-label',c.all);renderGallery();themeLabel();if($('#viewer').open)showImage();}
function themeLabel(){const light=document.documentElement.dataset.theme==='light',button=$('#theme'),key=light?'dark':'light';button.setAttribute('aria-label',COPY[lang][key]);button.setAttribute('title',COPY[lang][key]);button.setAttribute('aria-pressed',String(light));button.querySelector('.theme-label').textContent=({uk:['Світла','Темна'],ru:['Светлая','Тёмная'],en:['Light','Dark'],de:['Hell','Dunkel'],pl:['Jasny','Ciemny']})[lang][light?1:0];button.querySelector('svg').innerHTML=light?'<path d="M20 15.5A9 9 0 0 1 8.5 4a9 9 0 1 0 11.5 11.5Z"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>';document.querySelector('meta[name="theme-color"]').content=light?'#f2eee6':'#171c18';}
document.documentElement.dataset.theme=read('km-photography-theme')==='light'?'light':'dark';
$('#theme').onclick=()=>{const t=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=t;save('km-photography-theme',t);themeLabel()};
$('#language').onchange=e=>{lang=e.target.value;save('km-hub-language',lang);const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);render()};
function showImage(){window.getSelection()?.removeAllRanges();const list=visible(),p=list[current];$('#viewer-image').src=asset(p,p.fullSize||2400);$('#viewer-image').alt=title(p);$('#viewer-title').textContent=title(p);$('#viewer-series').textContent=groupTitle(p.group);$('#viewer-count').textContent=`${String(current+1).padStart(2,'0')} / ${String(list.length).padStart(2,'0')}`;[list[(current+1)%list.length],list[(current-1+list.length)%list.length]].forEach(n=>{const img=new Image();img.src=asset(n,n.fullSize||2400)})}
function openViewer(i,trigger){current=i;returnTo=trigger;showImage();$('#viewer').showModal();document.body.classList.add('viewing');$('#close').focus()}
function move(n){current=(current+n+visible().length)%visible().length;showImage()}
$('#close').onclick=()=>$('#viewer').close();$('#viewer').addEventListener('close',()=>{document.body.classList.remove('viewing');returnTo?.focus()});$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#viewer').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}if(e.key==='ArrowRight'){e.preventDefault();move(1)}});
// Prevent native selection and image dragging while preserving keyboard and touch navigation.
$('#viewer').addEventListener('selectstart',e=>e.preventDefault());
$('#viewer-image').addEventListener('dragstart',e=>e.preventDefault());
let touch;$('#viewer-image').addEventListener('touchstart',e=>{if(e.touches.length===1)touch=[e.touches[0].clientX,e.touches[0].clientY];else touch=null},{passive:true});$('#viewer-image').addEventListener('touchend',e=>{if(!touch)return;const dx=e.changedTouches[0].clientX-touch[0],dy=e.changedTouches[0].clientY-touch[1];if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)move(dx<0?1:-1);touch=null},{passive:true});
$('#brief').onsubmit=e=>{e.preventDefault();const c=COPY[lang],body=`${c.typeLabel}: ${$('#shoot-type').value}\n${c.whereLabel}: ${$('#where').value}\n\n${$('#message').value}`;location.href='mailto:m.krystyna.197@gmail.com?subject='+encodeURIComponent('Photography — '+$('#shoot-type').value)+'&body='+encodeURIComponent(body)};

function renderHero(){const p=heroPhotos[heroCurrent],img=$('#hero-photo');img.src=asset(p,1440);img.alt=title(p);img.style.objectFit=p.width<p.height?'contain':'cover';document.querySelector('.hero-image [data-t="heroCaption"]').textContent=title(p);$('#hero-count').textContent=String(heroCurrent+1).padStart(2,'0')+' / '+heroPhotos.length;$('#hero-prev').setAttribute('aria-label',COPY[lang].prev);$('#hero-next').setAttribute('aria-label',COPY[lang].next);document.querySelector('.hero-image').setAttribute('aria-label',COPY[lang].all);}
function moveHero(step){heroCurrent=(heroCurrent+step+heroPhotos.length)%heroPhotos.length;renderHero()}
$('#hero-prev').onclick=()=>moveHero(-1);$('#hero-next').onclick=()=>moveHero(1);
document.querySelector('.hero-image').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveHero(e.key==='ArrowLeft'?-1:1)}});
let heroTouch=null;document.querySelector('.hero-stage').addEventListener('touchstart',e=>{heroTouch=e.touches.length===1?[e.touches[0].clientX,e.touches[0].clientY]:null},{passive:true});document.querySelector('.hero-stage').addEventListener('touchend',e=>{if(!heroTouch)return;const dx=e.changedTouches[0].clientX-heroTouch[0],dy=e.changedTouches[0].clientY-heroTouch[1];if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)moveHero(dx<0?1:-1);heroTouch=null},{passive:true});

function initializeGalleryRoute(){
 const url=new URL(location.href);
 const requestedGroup=url.searchParams.get('group');
 const requestedCollection=collections.find(c=>c.id===(url.searchParams.get('series')==='river-bend'?'stone-horizon':url.searchParams.get('series')));
 active=groups.includes(requestedGroup)?requestedGroup:(requestedCollection?.group||'all');
 activeCollection=null;
 url.searchParams.delete('series');
 if(active==='all')url.searchParams.delete('group');else url.searchParams.set('group',active);
 history.replaceState(null,'',url);
}
initializeGalleryRoute();
$('#top-link').onclick=e=>{e.preventDefault();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};render();

// Revalidate restored/open pages without interrupting a draft or the image viewer.
let checkingRelease=false;
async function checkRelease(){
 if(checkingRelease||document.visibilityState==='hidden'||document.querySelector('#viewer').open||document.querySelector('#message').value||document.querySelector('#where').value)return;
 const current=document.querySelector('meta[name="photography-release"]')?.content;
 if(!current)return;
 checkingRelease=true;
 try{const response=await fetch('photography-release.json',{cache:'no-store'});if(!response.ok)return;const release=await response.json();const url=new URL(location.href);if(release.version&&release.version!==current&&url.searchParams.get('_release')!==release.version){url.searchParams.set('_release',release.version);location.replace(url.href)}}catch{}finally{checkingRelease=false}
}
window.addEventListener('pageshow',checkRelease);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkRelease()});


function selectDirection(direction){
 const video=direction==='video';
 document.querySelector('#series').hidden=video;
 document.querySelector('#photographs').hidden=video;
 document.querySelector('#video-portfolio').hidden=!video;
 document.querySelector('#direction-photo').setAttribute('aria-pressed',String(!video));
 document.querySelector('#direction-video').setAttribute('aria-pressed',String(video));
}
document.querySelector('#direction-photo').onclick=()=>selectDirection('photo');
document.querySelector('#direction-video').onclick=()=>selectDirection('video');
document.querySelectorAll('a[href="#series"]').forEach(a=>a.addEventListener('click',()=>selectDirection('photo')));
